set-variable.value:
@{
            try {
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                if (!contentType.StartsWith("multipart/form-data", StringComparison.OrdinalIgnoreCase)) { return null; }
                var fields = new JObject();
                string boundary = null;
                var cparts = contentType.Split(';');
                for (int i = 1; i < cparts.Length; i++) {
                    var eq = cparts[i].IndexOf('=');
                    if (eq > 0 && cparts[i].Substring(0, eq).Trim().Equals("boundary", StringComparison.OrdinalIgnoreCase)) {
                        if (boundary != null) { fields["#ambiguous"] = true; return fields; }
                        boundary = cparts[i].Substring(eq + 1).Trim().Trim('"');
                    }
                }
                if (string.IsNullOrEmpty(boundary)) { fields["#ambiguous"] = true; return fields; }
                var text = context.Request.Body.As<string>(preserveContent: true).Replace("\r\n", "\n");
                var delim = System.Text.RegularExpressions.Regex.Replace("--" + boundary, "[\\\\.*+?^$(){}|\\[\\]#\\s]", "\\$&");
                if (!System.Text.RegularExpressions.Regex.IsMatch(text, "(?m)^" + delim + "--[ \\t]*$")) { fields["#ambiguous"] = true; return fields; }
                var chunks = System.Text.RegularExpressions.Regex.Split(text, "(?m)^" + delim + "(?:--)?[ \\t]*$");
                var parameter = new System.Text.RegularExpressions.Regex("\\G\\s*;\\s*([^=;\"\\s]+)\\s*=\\s*(?:\"((?:[^\"\\\\]|\\\\.)*)\"|([^;\"\\s]*))\\s*");
                for (int i = 1; i < chunks.Length - 1; i++) {
                    var part = chunks[i];
                    if (part.StartsWith("\n")) { part = part.Substring(1); }
                    string headers = "";
                    string value = "";
                    if (part.StartsWith("\n")) {
                        value = part.Substring(1);
                    } else {
                        var sep = part.IndexOf("\n\n", StringComparison.Ordinal);
                        if (sep < 0) { fields["#ambiguous"] = true; return fields; }
                        headers = part.Substring(0, sep);
                        value = part.Substring(sep + 2);
                    }
                    var dispositions = 0;
                    var names = 0;
                    string name = null;
                    foreach (var line in System.Text.RegularExpressions.Regex.Replace(headers, "\n[ \\t]+", " ").Split('\n')) {
                        if (!line.StartsWith("content-disposition:", StringComparison.OrdinalIgnoreCase)) { continue; }
                        dispositions++;
                        var disposition = line.Substring(line.IndexOf(':') + 1).Trim();
                        var pos = disposition.IndexOf(';');
                        if (pos < 0) { pos = disposition.Length; }
                        while (pos < disposition.Length) {
                            var pm = parameter.Match(disposition, pos);
                            if (!pm.Success) { fields["#ambiguous"] = true; return fields; }
                            pos = pm.Index + pm.Length;
                            var pk = pm.Groups[1].Value.ToLowerInvariant();
                            if (pk == "name*") { fields["#ambiguous"] = true; return fields; }
                            if (pk == "name") {
                                names++;
                                name = pm.Groups[2].Success ? System.Text.RegularExpressions.Regex.Replace(pm.Groups[2].Value, "\\\\(.)", "$1") : pm.Groups[3].Value;
                            }
                        }
                    }
                    if (dispositions > 1 || names > 1) { fields["#ambiguous"] = true; return fields; }
                    if (name == null) { continue; }
                    var key = name.Trim().ToLowerInvariant();
                    if (!(fields[key] is JArray)) { fields[key] = new JArray(); }
                    if (value.EndsWith("\n")) { value = value.Substring(0, value.Length - 1); }
                    ((JArray)fields[key]).Add(value.Length > 256 ? value.Substring(0, 256) : value);
                }
                return fields;
            } catch {
                var failed = new JObject();
                failed["#ambiguous"] = true;
                return failed;
            }
        }

@{
            try {
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                var lengthText = context.Request.Headers.GetValueOrDefault("Content-Length", "0");
                if (lengthText.Length > 8 || (lengthText.Length == 8 && string.CompareOrdinal(lengthText, "25000000") > 0)) { return ""; }
                var model = "";
                var fields = context.Variables.GetValueOrDefault<JObject>("formFields", null);
                if (fields != null) {
                    var mf = fields["model"] as JArray;
                    model = (mf != null && mf.Count == 1 && (fields["#ambiguous"] as JValue) == null) ? ((string)mf[0]).Trim() : "";
                } else {
                    var body = context.Request.Body.As<JObject>(preserveContent: true);
                    model = (string)body["model"] ?? "";
                }
                return System.Text.RegularExpressions.Regex.IsMatch(model, "^[A-Za-z0-9._-]{1,64}$") ? model : "";
            } catch {
                return "";
            }
        }

@{
            try {
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                var fields = context.Variables.GetValueOrDefault<JObject>("formFields", null);
                if (fields != null) {
                    if ((fields["#ambiguous"] as JValue) != null) { return true; }
                    var wg = fields["web_grounding"] as JArray;
                    if (wg == null) { return false; }
                    if (wg.Count > 1) { return true; }
                    var gv = ((string)wg[0]).Trim().ToLowerInvariant();
                    return gv != "false" && gv != "0";
                }
                var body = context.Request.Body.As<JObject>(preserveContent: true);
                var token = body["web_grounding"];
                if (token == null) { return false; }
                return token.ToString().ToLowerInvariant() == "true";
            } catch {
                return false;
            }
        }

emit-metric.value:
@{
                    try {
                        var body = context.Response.Body.As<JObject>(preserveContent: true);
                        var data = body["data"] as JArray;
                        return data != null ? (double)data.Count : 1.0;
                    } catch {
                        return 1.0;
                    }
                }
